{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "summit_title",
        "intro_text",
        "itinerary_card",
        "quick_actions_title",
        "quick_actions_stack",
        "sources_title",
        "sources_stack"
      ]
    },
    "summit_title": {
      "type": "Text",
      "props": {
        "text": "Future Horizon Tech Summit: Berlin 2025",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "This personalized itinerary focuses on the AI Ethics and Green Tech tracks, adhering to your 10:00 AM start time and lunch break requirements. AI Ethics sessions have been prioritized in instances of overlap."
      },
      "children": []
    },
    "itinerary_card": {
      "type": "Card",
      "props": {},
      "children": [
        "itinerary_header_stack",
        "itinerary_image",
        "itinerary_table"
      ]
    },
    "itinerary_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "align": "center",
        "gap": "sm"
      },
      "children": [
        "calendar_icon",
        "itinerary_title"
      ]
    },
    "calendar_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/calendar.svg"
      },
      "children": []
    },
    "itinerary_title": {
      "type": "Text",
      "props": {
        "text": "Personalized AI Ethics & Green Tech Itinerary",
        "variant": "h2"
      },
      "children": []
    },
    "itinerary_image": {
      "type": "Image",
      "props": {
        "url": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/83/Brandenburger_Tor_abends.jpg/1200px-Brandenburger_Tor_abends.jpg",
        "fit": "cover"
      },
      "children": []
    },
    "itinerary_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "date",
            "label": "Date"
          },
          {
            "key": "time",
            "label": "Time"
          },
          {
            "key": "session",
            "label": "Session"
          },
          {
            "key": "location",
            "label": "Location"
          }
        ],
        "rows": [
          {
            "date": "2025-05-15",
            "time": "10:30 AM",
            "session": "AI Ethics in Healthcare",
            "location": "Room A"
          },
          {
            "date": "2025-05-15",
            "time": "12:00 PM",
            "session": "Lunch Break",
            "location": "Dining Hall"
          },
          {
            "date": "2025-05-15",
            "time": "01:00 PM",
            "session": "Solar Power Innovations",
            "location": "Room C"
          },
          {
            "date": "2025-05-15",
            "time": "02:30 PM",
            "session": "Algorithmic Bias Workshop",
            "location": "Room A"
          },
          {
            "date": "2025-05-16",
            "time": "10:30 AM",
            "session": "Responsible AI Frameworks",
            "location": "Room A"
          },
          {
            "date": "2025-05-16",
            "time": "12:00 PM",
            "session": "Smart Grid Management",
            "location": "Room C"
          },
          {
            "date": "2025-05-16",
            "time": "01:00 PM",
            "session": "Lunch Break",
            "location": "Dining Hall"
          },
          {
            "date": "2025-05-16",
            "time": "02:00 PM",
            "session": "Carbon Capture Technology",
            "location": "Room C"
          },
          {
            "date": "2025-05-17",
            "time": "10:00 AM",
            "session": "Ethics of Autonomous Vehicles",
            "location": "Room A"
          },
          {
            "date": "2025-05-17",
            "time": "11:30 AM",
            "session": "Sustainable Battery Disposal",
            "location": "Room C"
          },
          {
            "date": "2025-05-17",
            "time": "12:30 PM",
            "session": "Lunch Break",
            "location": "Dining Hall"
          },
          {
            "date": "2025-05-17",
            "time": "01:30 PM",
            "session": "Closing Plenary",
            "location": "Main Hall"
          }
        ],
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "session",
        "highlightColumns": [
          "time",
          "location"
        ]
      },
      "children": []
    },
    "quick_actions_title": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "wrap": "wrap"
      },
      "children": [
        "download_button",
        "map_button"
      ]
    },
    "download_button": {
      "type": "Button",
      "props": {
        "label": "Download PDF"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://futurehorizon.tech/itinerary/download"
          }
        }
      },
      "children": []
    },
    "map_button": {
      "type": "Button",
      "props": {
        "label": "Venue Map"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://futurehorizon.tech/berlin/map"
          }
        }
      },
      "children": []
    },
    "sources_title": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "sources_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "summit_schedule_button",
        "berlin_guide_button"
      ]
    },
    "summit_schedule_button": {
      "type": "Button",
      "props": {
        "label": "Summit Schedule",
        "variant": "borderless"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://futurehorizon.tech/sessions"
          }
        }
      },
      "children": []
    },
    "berlin_guide_button": {
      "type": "Button",
      "props": {
        "label": "Berlin Event Guide",
        "variant": "borderless"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.visitberlin.de/en/events-berlin"
          }
        }
      },
      "children": []
    }
  }
}
